import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const u=JSON.parse('{"title":"生日聚会邀请（教材听力练习）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/16-anna-birthday-party-invitation.md","filePath":"zh/more/maltese/practice/emails/16-anna-birthday-party-invitation.md"}'),e={name:"zh/more/maltese/practice/emails/16-anna-birthday-party-invitation.md"},o=r('<h1 id="生日聚会邀请-教材听力练习" tabindex="-1">生日聚会邀请（教材听力练习） <a class="header-anchor" href="#生日聚会邀请-教材听力练习" aria-label="Permalink to &quot;生日聚会邀请（教材听力练习）&quot;">​</a></h1><p><strong>场景：</strong> Anna 给 Maria 写邮件，邀请她来参加自己在 Għadira 湾举行的 15 岁生日聚会。这是 PDF 中的教材原文邮件，括号内为听力填空选项。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data（日期）：</strong> 30 ta&#39; Ġunju, 2023 <strong>Suġġett（主题）：</strong> Festin ta&#39; għeluq snini</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Data:</strong> 30 ta&#39; Ġunju, 2023 <strong>Suġġett:</strong> Festin ta&#39; għeluq snini</p><p>Ħelow Maria!</p><p>Nispera li tinsab tajba. Bħalma taf, (ilbieraħ / dalwaqt / sena oħra) se nagħlaq 15-il sena u qed nibgħatek din l-ittra elettronika sabiex nistednek għall-festin ta&#39; għeluq snini.</p><p>Il-festin se jkun nhar (il-ġimgħa l-oħra / ix-xahar id-dieħel / il-Ġimgħa 14 ta&#39; Lulju).</p><p>Fis- (tmienja ta&#39; flgħaxija / sitta ta&#39; flgħodu / sitta ta&#39; flgħaxija) se niltaqgħu (quddiem / fuq / taħt) il-knisja biex minn hemm niġru bil-van kollha f&#39;daqqa li se joħodna l-bajja tal-Għadira.</p><p>Fil-festin se jkun hemm ħafna ikel, xorb, logħob u mużika! Tinsiex tiġi bil-malja u ġġib xugaman għax xi qabża l-baħar ma tonqosx!</p><p>Jekk jogħġbok agħtini risposta sa (bħal-lum ġimgħa / xahar ieħor).</p><p>Nispera li narak ħalli nieħdu gost flimkien!</p><p>Ċaw! Anna</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：maria.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:maria.b@gmail.com" target="_blank" rel="noreferrer">maria.b@gmail.com</a></td><td>邮箱地址</td><td>收件人的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>发件人的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 30 ta&#39; Ġunju, 2023</p><p><strong>整句：</strong> 日期：2023 年 6 月 30 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>30</td><td>三十</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ġunju</td><td>六月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Festin ta&#39; għeluq snini</p><p><strong>整句：</strong> 主题：我生日的庆祝聚会</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;；原文印刷为 <code>Suggett</code></td></tr><tr><td>Festin</td><td>庆祝聚会；小型聚会</td><td>借词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>għeluq</td><td>生日</td><td>字面&quot;结束/届满&quot;；<code>għeluq snin</code> 即&quot;生日&quot;</td></tr><tr><td>snini</td><td>我的岁数；我的生日</td><td><code>snin</code>（年，复数）+ <code>-i</code>（我的）</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Ħelow Maria!</p><p><strong>整句：</strong> 你好 Maria！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ħelow</td><td>你好</td><td>非正式问候，借词 hello</td></tr><tr><td>Maria</td><td>Maria</td><td>人名</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li tinsab tajba.</p><p><strong>整句：</strong> 希望你一切都好。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>tinsab</td><td>你处于；你在</td><td><code>tinsab</code> 第二人称</td></tr><tr><td>tajba</td><td>好的</td><td>阴性单数形容词</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Bħalma taf, (ilbieraħ / dalwaqt / sena oħra) se nagħlaq 15-il sena u qed nibgħatek din l-ittra elettronika sabiex nistednek għall-festin ta&#39; għeluq snini.</p><p><strong>整句：</strong> 如你所知，（昨天 / 很快 / 另一年）我就满 15 岁了，我发这封邮件是为了邀请你来参加我的生日聚会。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Bħalma</td><td>正如</td><td><code>bħal</code>+<code>ma</code></td></tr><tr><td>taf</td><td>你知道</td><td>第二人称单数</td></tr><tr><td>ilbieraħ</td><td>昨天</td><td>听力选项①</td></tr><tr><td>dalwaqt</td><td>很快</td><td>听力选项②</td></tr><tr><td>sena oħra</td><td>另一年；再一年</td><td>听力选项③</td></tr><tr><td>se</td><td>将要</td><td>将来时标记</td></tr><tr><td>nagħlaq</td><td>我满（岁）</td><td>字面&quot;关闭&quot;，指岁数届满</td></tr><tr><td>15-il sena</td><td>15 岁</td><td>数字+<code>-il</code>+sena 的结构</td></tr><tr><td>qed</td><td>正在</td><td>进行时标记</td></tr><tr><td>nibgħatek</td><td>我发给你</td><td><code>nibgħat</code>+<code>-ek</code>（你）</td></tr><tr><td>din</td><td>这</td><td>阴性指示代词</td></tr><tr><td>l-ittra elettronika</td><td>电子邮件</td><td>ittra（信）+elettronika（电子的）</td></tr><tr><td>sabiex</td><td>为了</td><td>书面连词</td></tr><tr><td>nistednek</td><td>我邀请你</td><td><code>nistedin</code>+<code>-ek</code></td></tr><tr><td>għall-festin</td><td>来参加聚会</td><td><code>għal</code>+<code>il-festin</code></td></tr><tr><td>ta&#39; għeluq snini</td><td>我生日的</td><td>għeluq（生日）+snin（复数&quot;岁&quot;）+-i（我的）</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Il-festin se jkun nhar (il-ġimgħa l-oħra / ix-xahar id-dieħel / il-Ġimgħa 14 ta&#39; Lulju).</p><p><strong>整句：</strong> 聚会将在（下周 / 下个月 / 7 月 14 日星期五）那天举行。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Il-festin</td><td>聚会</td><td><code>festin</code> 小型聚会，借词</td></tr><tr><td>se jkun</td><td>将会是</td><td>将来时</td></tr><tr><td>nhar</td><td>在……那天</td><td>字面&quot;天&quot;</td></tr><tr><td>il-ġimgħa l-oħra</td><td>下周</td><td>选项①</td></tr><tr><td>ix-xahar id-dieħel</td><td>下个月</td><td>选项②：字面&quot;进入的月份&quot;</td></tr><tr><td>il-Ġimgħa 14 ta&#39; Lulju</td><td>7 月 14 日星期五</td><td>选项③</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Fis- (tmienja ta&#39; flgħaxija / sitta ta&#39; flgħodu / sitta ta&#39; flgħaxija) se niltaqgħu (quddiem / fuq / taħt) il-knisja biex minn hemm niġru bil-van kollha f&#39;daqqa li se joħodna l-bajja tal-Għadira.</p><p><strong>整句：</strong> 我们将在（晚上 8 点 / 早上 6 点 / 晚上 6 点）在（教堂前 / 教堂上 / 教堂下）见面，然后一起坐面包车去 Għadira 海滩。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>tmienja ta&#39; flgħaxija</td><td>晚上八点</td><td>选项①（<code>filgħaxija</code>）</td></tr><tr><td>sitta ta&#39; flgħodu</td><td>早上六点</td><td>选项②（<code>filgħodu</code>）</td></tr><tr><td>sitta ta&#39; flgħaxija</td><td>晚上六点</td><td>选项③</td></tr><tr><td>quddiem</td><td>前面</td><td>选项①方位</td></tr><tr><td>fuq</td><td>上面</td><td>选项②</td></tr><tr><td>taħt</td><td>下面</td><td>选项③</td></tr><tr><td>il-knisja</td><td>教堂</td><td>阴性名词，带定冠词</td></tr><tr><td>biex</td><td>为了</td><td>目的连词</td></tr><tr><td>minn hemm</td><td>从那里</td><td>地点短语</td></tr><tr><td>niġru</td><td>我们乘车疾驰</td><td><code>iġri</code> 第一人称复数</td></tr><tr><td>bil-van</td><td>坐面包车</td><td><code>b&#39;</code>+<code>il-van</code></td></tr><tr><td>kollha f&#39;daqqa</td><td>大家一起</td><td>kollha（全部）+f&#39;daqqa（一下子）</td></tr><tr><td>se joħodna</td><td>将带我们</td><td><code>jieħu</code>（带）+-na（我们）</td></tr><tr><td>l-bajja tal-Għadira</td><td>Għadira 海滩</td><td>bajja（海滩）+ta&#39;（的）+Għadira（地名）</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Fil-festin se jkun hemm ħafna ikel, xorb, logħob u mużika!</p><p><strong>整句：</strong> 聚会上将会有很多食物、饮料、游戏和音乐！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Fil-festin</td><td>在聚会上</td><td><code>f&#39;</code>+<code>il-festin</code></td></tr><tr><td>se jkun hemm</td><td>将会有</td><td>存在结构</td></tr><tr><td>ħafna</td><td>很多</td><td>数量词</td></tr><tr><td>ikel</td><td>食物</td><td>阳性名词</td></tr><tr><td>xorb</td><td>饮料</td><td>名词</td></tr><tr><td>logħob</td><td>游戏</td><td>名词</td></tr><tr><td>mużika</td><td>音乐</td><td>借词 music</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Tinsiex tiġi bil-malja u ġġib xugaman għax xi qabża l-baħar ma tonqosx!</p><p><strong>整句：</strong> 别忘了穿泳衣、带毛巾，因为下水游泳是少不了的！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tinsiex</td><td>别忘了</td><td><code>tinsa</code>+<code>x</code>，祈使否定</td></tr><tr><td>tiġi</td><td>你来</td><td>第二人称单数</td></tr><tr><td>bil-malja</td><td>穿泳衣</td><td><code>b&#39;</code>+<code>il-malja</code>（malja 泳衣）</td></tr><tr><td>u</td><td>并且</td><td>连词</td></tr><tr><td>ġġib</td><td>你带</td><td>第二人称单数</td></tr><tr><td>xugaman</td><td>毛巾</td><td>借词</td></tr><tr><td>għax</td><td>因为</td><td>原因连词</td></tr><tr><td>xi</td><td>某种</td><td>限定词</td></tr><tr><td>qabża l-baħar</td><td>跳进海里</td><td>qabża（跳）+l-baħar（海）</td></tr><tr><td>ma tonqosx</td><td>不会缺；少不了</td><td><code>ma</code>+<code>tonqos</code>+<code>x</code> 否定</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Jekk jogħġbok agħtini risposta sa (bħal-lum ġimgħa / xahar ieħor).</p><p><strong>整句：</strong> 请在一周内（/再过一个月）给我答复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jekk jogħġbok</td><td>请</td><td>字面&quot;如果你乐意&quot;</td></tr><tr><td>agħtini</td><td>给我</td><td><code>agħti</code>（给）+-ni（我）</td></tr><tr><td>risposta</td><td>答复</td><td>借词 risposta</td></tr><tr><td>sa</td><td>到……为止</td><td>介词</td></tr><tr><td>bħal-lum ġimgħa</td><td>一周后的今天</td><td>选项①（OCR 另有乱码项，疑为 <code>il-biċċa l-oħra</code>，存疑）</td></tr><tr><td>xahar ieħor</td><td>再过一个月</td><td>选项②</td></tr></tbody></table><h3 id="_9" tabindex="-1">9. <a class="header-anchor" href="#_9" aria-label="Permalink to &quot;9.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li narak ħalli nieħdu gost flimkien!</p><p><strong>整句：</strong> 希望见到你，让我们一起玩个开心！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数</td></tr><tr><td>li</td><td>引出从句</td><td>连词</td></tr><tr><td>narak</td><td>我见到你</td><td><code>nara</code>+<code>-k</code></td></tr><tr><td>ħalli</td><td>这样；以便</td><td>口语连词</td></tr><tr><td>nieħdu gost</td><td>我们玩得开心</td><td><code>ieħu gost</code> 惯用语&quot;取乐&quot;</td></tr><tr><td>flimkien</td><td>一起</td><td>副词</td></tr></tbody></table><h3 id="_10" tabindex="-1">10. <a class="header-anchor" href="#_10" aria-label="Permalink to &quot;10.&quot;">​</a></h3><p><strong>Malti:</strong> Ċaw!</p><p><strong>整句：</strong> 拜拜！</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Ċaw</td><td>拜拜</td><td>非正式告别</td></tr></tbody></table><p><strong>Malti:</strong> Anna</p><p><strong>整句：</strong> Anna（署名）</p><h2 id="附-第-17-页正式-非正式开头结尾对比表" tabindex="-1">附：第 17 页正式 / 非正式开头结尾对比表 <a class="header-anchor" href="#附-第-17-页正式-非正式开头结尾对比表" aria-label="Permalink to &quot;附：第 17 页正式 / 非正式开头结尾对比表&quot;">​</a></h2><table><thead><tr><th>项目</th><th>正式（Formali）</th><th>非正式（Informali）</th></tr></thead><tbody><tr><td>开头</td><td>Għażiż/a Sur ..., Sinjura ...（亲爱的先生……/女士……）</td><td>Ħelow, Ħaw&#39;, Bongu...（你好，嗨，早安……）</td></tr><tr><td>结尾</td><td>Saħħa, Tislijiet, Dejjem tiegħek（保重，此致敬意，永远你的）</td><td>Ċaw, Sellili, Narak!（拜拜，代我问候，再见！）</td></tr></tbody></table>',63),i=[o];function n(l,h,s,g,b,c){return d(),a("div",null,i)}const p=t(e,[["render",n]]);export{u as __pageData,p as default};
